def run(bs,Pkeys,tf):
    res=[]
    for b in bs:
        T=np.tanh(b*t)
        feats=[np.ones_like(t),T]
        names=['1','T']
        for k in Pkeys:
            for g,gn in tf:
                feats.append(Pf[k]*g); names.append(k+'*'+gn)
        A=np.column_stack(feats)
        c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
        r=dP_dt-A@c
        res.append((np.mean(r**2)/np.var(dP_dt),b,names,c))
    return min(res,key=lambda x:x[0])
